A","file":"chunks/ceres-client-8.js","sourcesContent":["<template>\n    <div v-if=\"facet.name\" class=\"card pt-4 border-0\" :class=\"facet.cssClass\">\n        <div class=\"h3 title py-0\">{{ facetName }}</div>\n\n        <div v-if=\"facet.type === 'price'\">\n            <item-filter-price></item-filter-price>\n        </div>\n\n        <div v-else class=\"form-check-wrapper\" v-for=\"value in facets\" :key=\"value.id\" :class=\"value.cssClass\">\n            <div class=\"form-check mb-0 pl-0\">\n                <input :id=\"'option-' + value.id + '-' + _uid\" class=\"form-check-input d-none\" type=\"checkbox\" :checked=\"isSelected(value.id)\" @change=\"updateFacet(value)\" :disabled=\"isLoading || value.count <= 0\">\n                <label :for=\"'option-' + value.id + '-' + _uid\" class=\"form-check-label\" :class=\"[paddingClasses, isSelected(value.id) ? 'bg-appearance' : '', 'option-' + value.id]\" :style=\"paddingInlineStyles\">\n                    <div class=\"d-flex\">\n                        <span class=\"flex-grow-1\">{{ value.name }}</span>\n                        <div class=\"filter-badge\">{{ value.count }}</div>\n                    </div>\n                </label>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\nimport ItemFilterPrice from \"./ItemFilterPrice.vue\";\n\nexport default {\n\n    name: \"item-filter\",\n\n    components:\n    {\n        ItemFilterPrice\n    },\n\n    props:\n    {\n        facet:\n        {\n            type: Object\n        },\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        }\n    },\n\n    computed:\n    {\n        facets()\n        {\n            return this.facet.values;\n        },\n\n        facetName()\n        {\n            if (this.facet.translationKey && this.facet.translationKey.length > 0)\n            {\n                return this.$translate(\"Ceres::Template.\" + this.facet.translationKey);\n            }\n\n            return this.facet.name;\n        },\n\n        ...mapState({\n            selectedFacets: state => state.itemList.selectedFacets,\n            isLoading: state => state.itemList.isLoading\n        })\n    },\n\n    methods:\n    {\n        updateFacet(facetValue)\n        {\n            const toolbarElements = document.getElementsByClassName(\"widget-toolbar\");\n\n            for (const toolbarElement of toolbarElements)\n            {\n                if (toolbarElement.contains(this.$vnode.elm))\n                {\n                    window.localStorage.setItem(\"openFilterToolbar\", true);\n                }\n            }\n\n            this.$store.dispatch(\"selectFacet\", { facetValue });\n        },\n\n        isSelected(facetValueId)\n        {\n            return this.selectedFacets.findIndex(selectedFacet => selectedFacet.id === facetValueId) > -1;\n        }\n    }\n}\n</script>\n","<template>\n    <div v-if=\"filterListBulk\">\n        <item-filter v-for=\"facet in facets\"\n            :facet=\"facet\"\n            :key=\"facet.id\"\n            :padding-classes=\"paddingClasses\"\n            :padding-inline-styles=\"paddingInlineStyles\">\n        </item-filter>\n    </div>\n\n    <div v-else class=\"filter-wrapper\" v-show=\"facets && facets.length > 0\">\n        <a class=\"btn btn-link filter-toggle\" data-toggle=\"collapse\" :href=\"'#filter-collapse_' + _cid\" aria-expanded=\"false\" :aria-controls=\"'filter-collapse_' + _cid\">\n            <i class=\"fa fa-sliders default-float\" aria-hidden=\"true\"></i> {{ $translate(\"Ceres::Template.itemFilter\") }}\n        </a>\n\n        <div v-open-filter-toolbar class=\"filter-collapse collapse\" :id=\"'filter-collapse_' + _cid\">\n            <div class=\"container-max page-content component-loading\" :class=\"{ 'is-loading': isLoading }\">\n                <div class=\"card-columns\">\n                    <item-filter v-for=\"facet in facets\" :facet=\"facet\" :key=\"facet.id\"></item-filter>\n                </div>\n\n                <div class=\"row\">\n                    <div class=\"col-12 text-right\">\n                        <button type=\"button\" class=\"btn btn-primary btn-medium-large\" data-toggle=\"collapse\" :href=\"'#filter-collapse_' + _cid\" :aria-controls=\"'filter-collapse_' + _cid\">\n                            <i class=\"fa fa-times\" aria-hidden=\"true\"></i>\n                            <span>{{ $translate(\"Ceres::Template.itemClose\") }}&nbsp;</span>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\nimport ItemFilter from \"./ItemFilter.vue\";\nimport { ComponentIdMixin } from \"../../../mixins/componentId.mixin\";\n\nexport default {\n\n    name: \"item-filter-list\",\n\n    components:\n    {\n        ItemFilter\n    },\n\n    mixins: [ComponentIdMixin], // Experimental mixin, may be removed in the future.\n\n    props: {\n        filterListBulk: Boolean,\n        facetData:\n        {\n            type: Array,\n            default()\n            {\n                return [];\n            }\n        },\n        allowedFacetsTypes:\n        {\n            type: Array,\n            default: () => []\n        },\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        }\n    },\n\n    computed:\n    {\n        ...mapState({\n            facets(state)\n            {\n                if (!this.allowedFacetsTypes.length)\n                {\n                    return state.itemList.facets;\n                }\n\n                return state.itemList.facets\n                    .filter(facet => this.allowedFacetsTypes.includes(facet.id) || this.allowedFacetsTypes.includes(facet.type));\n            },\n            isLoading: state => state.itemList.isLoading,\n            selectedFacets: state => state.itemList.selectedFacets\n        })\n    },\n\n    created()\n    {\n        if (!this.$store.state.itemList.facets?.length)\n        {\n            this.$store.commit(\"addFacets\", this.facetData);\n        }\n    }\n}\n</script>\n","<template>\n    <div class=\"item-filter-price\">\n        <div class=\"input-group\">\n            <div class=\"input-group-prepend\">\n                <span class=\"input-group-text\">{{ currency }}</span>\n            </div>\n\n            <input type=\"number\"\n                   class=\"form-control\"\n                   @focus=\"selectAll($event)\"\n                   placeholder=\"Min\"\n                   v-model=\"priceMin\"\n                   :aria-label=\"$translate('Ceres::Template.itemFilterPriceMin')\">\n        </div>\n\n        <div class=\"input-group\">\n            <div class=\"input-group-prepend\">\n                <span class=\"input-group-text\">{{ currency }}</span>\n            </div>\n\n            <input type=\"number\"\n                   class=\"form-control\"\n                   @focus=\"selectAll($event)\"\n                   placeholder=\"Max\"\n                   v-model=\"priceMax\"\n                   :aria-label=\"$translate('Ceres::Template.itemFilterPriceMax')\">\n        </div>\n\n        <button type=\"button\" class=\"btn btn-primary btn-appearance\" :class=\"{'disabled': isDisabled}\" v-tooltip\n                data-toggle=\"tooltip\" data-placement=\"top\" @click=\"triggerFilter()\" :title=\"$translate('Ceres::Template.itemApply')\" :aria-label=\"$translate('Ceres::Template.itemFilterButton')\">\n            <icon icon=\"check\" :loading=\"isLoading\"></icon>\n        </button>\n    </div>\n</template>\n\n<script>\nimport UrlService from \"../../../services/UrlService\";\nimport { mapState } from \"vuex\";\n\nexport default {\n    data()\n    {\n        return {\n            priceMin: \"\",\n            priceMax: \"\",\n            currency: App.activeCurrency\n        };\n    },\n\n    mounted()\n    {\n        const urlParams = UrlService.getUrlParams(document.location.search);\n\n        this.priceMin = urlParams.priceMin || \"\";\n        this.priceMax = urlParams.priceMax || \"\";\n    },\n\n    computed:\n    {\n        isDisabled()\n        {\n            return (this.priceMin === \"\" && this.priceMax === \"\") ||\n                (parseInt(this.priceMin) >= parseInt(this.priceMax)) ||\n                this.isLoading;\n        },\n\n        ...mapState({\n            isLoading: state => state.itemList.isLoading\n        })\n    },\n\n    methods:\n    {\n        selectAll(event)\n        {\n            event.target.select();\n        },\n\n        triggerFilter()\n        {\n            if (!this.isDisabled)\n            {\n                window.localStorage.setItem(\"openFilterToolbar\", true);\n                this.$store.dispatch(\"selectPriceFacet\", { priceMin: this.priceMin, priceMax: this.priceMax });\n            }\n        }\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _vm.facet.name\n    ? _c(\n        \"div\",\n        { staticClass: \"card pt-4 border-0\", class: _vm.facet.cssClass },\n        [\n          _c(\"div\", { staticClass: \"h3 title py-0\" }, [\n            _vm._v(_vm._s(_vm.facetName))\n          ]),\n          _vm._v(\" \"),\n          _vm.facet.type === \"price\"\n            ? _c(\"div\", [_c(\"item-filter-price\")], 1)\n            : _vm._l(_vm.facets, function(value) {\n                return _c(\n                  \"div\",\n                  {\n                    key: value.id,\n                    staticClass: \"form-check-wrapper\",\n                    class: value.cssClass\n                  },\n                  [\n      