        return this.$translate(\"Ceres::Template.contactAcceptPrivacyPolicy2\", {policy: html});\n\n            } else {\n\n                const contactPrivacyPolicy = this.$translate(\"Ceres::Template.contactPrivacyPolicy\", {\"hyphen\": \"&shy;\"});\n                const html = `\n                    <!----><a href=\"${ App.urls.privacyPolicy }\" target=\"_blank\" class=\"text-appearance\">\n                        <span>${ contactPrivacyPolicy }</span>\n                    </a><!---->\n                `;\n\n                return this.$translate(\"Ceres::Template.contactAcceptPrivacyPolicy\", {policy: html});\n\n            }\n        }\n    },\n\n    methods:\n    {\n        onValueChanged(value)\n        {\n            this.$emit(\"input\", value);\n        }\n    }\n}\n</script>","<template>\n    <div>\n        <form ref=\"form\" method=\"post\" class=\"mb-3 login-pwd-reset\">\n            <div class=\"input-unit\" data-validate=\"mail\">\n                <input type=\"email\" name=\"email\" autocomplete=\"email\" data-testing=\"guest-login-input\" :id=\"_uid\" v-model=\"email\" data-autofocus>\n                <label :for=\"_uid\">{{ $translate(\"Ceres::Template.loginEmail\") }}*</label>\n            </div>\n            <span class=\"error-msg\">{{ $translate(\"Ceres::Template.loginEnterConfirmEmail\") }}</span>\n            <div class=\"col-12 p-0\" v-if=\"enableConfirmingPrivacyPolicy\">\n                <accept-privacy-policy-check class=\"my-3 mb-0\" type=\"guest-login\" v-model=\"privacyPolicyAccepted\" @input=\"privacyPolicyValueChanged($event)\" :show-error=\"privacyPolicyShowError\"></accept-privacy-policy-check>\n            </div>\n            <div class=\"text-right\">\n                <button @click.prevent=\"validate\" :disabled=\"isDisabled\" class=\"btn btn-primary btn-medium btn-appearance\" :class=\"buttonSizeClass\" data-testing=\"guest-login-button\">\n                    {{ $translate(\"Ceres::Template.loginNext\") }}\n                    <icon icon=\"arrow-right\" :loading=\"isDisabled\"></icon>\n                </button>\n            </div>\n        </form>\n    </div>\n</template>\n\n<script>\nimport { ButtonSizePropertyMixin } from \"../../../mixins/buttonSizeProperty.mixin\";\n\nimport ApiService from \"../../../services/ApiService\";\nimport AutoFocusService from \"../../../services/AutoFocusService\";\nimport ValidationService from \"../../../services/ValidationService\";\nimport { navigateTo } from \"../../../services/UrlService\";\nimport { isDefined, isNullOrUndefined } from \"../../../helper/utils\";\nimport AcceptPrivacyPolicyCheck from \"../AcceptPrivacyPolicyCheck.vue\";\n\nexport default {\n    name: \"guest-login\",\n\n    mixins: [ButtonSizePropertyMixin],\n    components:\n    {\n        AcceptPrivacyPolicyCheck\n    },\n\n    props: {\n        backlink:\n        {\n            type: String\n        },\n        initialEmail:\n        {\n            type: String,\n            default: \"\"\n        }\n    },\n\n    data()\n    {\n        return {\n            email: \"\",\n            isDisabled: false,\n            privacyPolicyAccepted : false,\n            privacyPolicyShowError: false,\n            enableConfirmingPrivacyPolicy: App.config.global.registrationRequirePrivacyPolicyConfirmation,\n        };\n    },\n\n    created()\n    {\n        console.log(\"cre\"+this.checked)\n\n        if (!isNullOrUndefined(this.initialEmail) && this.initialEmail.length > 0)\n        {\n            this.email = this.initialEmail;\n        }\n    },\n\n    mounted()\n    {\n        console.log(\"moun\"+this.checked)\n\n        this.$nextTick(() =>\n        {\n            // for old login view only (input in modal)\n            if(!isNullOrUndefined(this.$parent.$refs.guestModal))\n            {\n                this.$parent.$refs.guestModal.addEventListener(\"hidden.bs.modal\", () =>\n                {\n                    this.email = \"\";\n                    ValidationService.unmarkAllFields(this.$refs.form);\n                });\n            }\n\n            AutoFocusService.triggerAutoFocus();\n        });\n    },\n\n    methods:\n    {\n        validate()\n        {\n            ValidationService.validate(this.$refs.form)\n                .done(() =>\n                {   \n                    if (!this.enableConfirmingPrivacyPolicy || this.privacyPolicyAccepted)\n                            {\n                    this.authGuest();\n                            }else\n                            {\n                                this.privacyPolicyShowError = true;\n\n                                NotificationService.error(\n                                    this.$translate(\"Ceres::Template.contactAcceptFormPrivacyPolicy\", { hyphen: \"&shy;\" })\n                                );\n                                this.resetRecaptcha();\n                            }\n                })\n                .fail(invalidFields =>\n                {\n                    ValidationService.markInvalidFields(invalidFields, \"error\");\n                    if (this.enableConfirmingPrivacyPolicy && !this.privacyPolicyAccepted)\n                    {\n                        this.privacyPolicyShowError = true;\n\n                        NotificationService.error(\n                            this.$translate(\"Ceres::Template.contactAcceptFormPrivacyPolicy\", { hyphen: \"&shy;\" })\n                        );\n                    }\n                });\n        },\n\n        authGuest()\n        {\n            this.isDisabled = true;\n\n            ApiService.post(\"/rest/io/guest\", { email: this.email })\n                .done(() =>\n                {\n                    navigateTo(\n                        isDefined(this.backlink) && this.backlink.length ? decodeURIComponent(this.backlink) : window.location.origin + (App.urls.includeLanguage ? \"/\" + App.language : \"\")\n                    );\n                })\n                .fail(() =>\n                {\n                    this.isDisabled = false;\n                });\n        },\n        privacyPolicyValueChanged(value)\n        {\n            this.privacyPolicyAccepted = value;\n\n            if (value)\n            {\n                this.privacyPolicyShowError = false;\n            }\n        },\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\n    \"div\",\n    { staticClass: \"form-check\", class: { error: _vm.showError } },\n    [\n      _c(\"input\", {\n        staticClass: \"form-check-input\",\n        attrs: {\n          type: \"checkbox\",\n          id: \"privacy-policy-accept\" + _vm._uid,\n          \"data-testing\": \"privacy-policy-accept-register\"\n        },\n        domProps: { checked: _vm.value },\n        on: {\n          change: function($event) {\n            return _vm.onValueChanged($event.target.checked)\n          }\n        }\n      }),\n      _vm._v(\" \"),\n      _c(\n        \"label\",\n        {\n          staticClass: \"form-check-label\",\n          attrs: { for: \"privacy-policy-accept\" + _vm._uid }\n        },\n        [\n          _c(\"span\", { domProps: { innerHTML: _vm._s(_vm.labelHtml) } }),\n          _c(\"sup\", [_vm._v(\"*\")])\n        ]\n      )\n    ]\n  )\n}\nvar staticRenderFns = []\nrender._withStripped = true\n\nexport { render, staticRenderFns }","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\"div\", [\n    _c(\n      \"form\",\n      {\n        ref: \"form\",\n        staticClass: \"mb-3 login-pwd-reset\",\n        attrs: { method: \"post\" }\n      },\n      [\n        _c(\n          \"div\",\n          { staticClass: \"input-unit\", attrs: { \"data-validate\": \"mail\" } },\n          [\n            _c(\"input\", {\n              directives: [\n                {\n                  name: \"model\",\n                  rawName: \"